import{cases}from'../data/cases.js?v=20261105-memes';import{items,rarities}from'../data/items.js?v=20261105-memes';import{loadState,saveState,pickCaseItem,addItem,addXp,weightedPick,gradeIndex,rng,entropySeed}from'./engine.js';
import{playSound}from'./sounds.js';
let state=loadState(),authUser=null,route=location.hash.slice(1)||'home',selectedUpgrade=[],openedCaseId=null,selectedBattle=[],menuOpen=false,upgradeMultiplier=2;
let rocketRun=null,rocketTimer=null,ladderRun=null,upgradeBusy=false;
const $=s=>document.querySelector(s),view=$('#view'),modalRoot=$('#modal-root'),toastRoot=$('#toast-root');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Math.floor(n).toLocaleString('ru-RU');
const rarity=name=>rarities.find(x=>x.name===name);
const api=async(path,options={})=>{const response=await fetch(path,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Ошибка соединения');return data};
function applyAccount(user){authUser=user;state={...loadState(user.id),...(user.state||{})};saveState(state,user.id);render()}
async function bootstrapAuth(){try{const response=await api('/api/me');if(response.user)applyAccount(response.user)}catch{}}
let stateSyncTimer;function queueStateSync(){if(!authUser)return;clearTimeout(stateSyncTimer);stateSyncTimer=setTimeout(()=>api('/api/state',{method:'POST',body:JSON.stringify(state)}).catch(()=>{}),350)}
const artFor=item=>items.find(x=>x.id===item.id)?.art||'assets/items/item-000.webp';
const itemVisual=item=>`<div class="item-art" style="--rarity-color:${item.color}"><img class="item-image" src="${artFor(item)}" alt="" loading="lazy"></div>`;
function sync(){saveState(state,authUser?.id||'guest');$('#balance').textContent=fmt(Math.max(0,state.balance));$('#inventory-count').textContent=state.inventory.length;$('#level-side').textContent=String(state.level).padStart(2,'0');const cap=state.level*500;$('#xp-label').textContent=`${state.xp} / ${cap} XP`;$(' .xp-track i')?.style.setProperty('width',`${state.xp/cap*100}%`);$('#daily-side').textContent=canDaily()?'Награда доступна':'Уже получена сегодня';$('#daily-text').textContent=canDaily()?'Забрать награду':'Получено';$('#daily-button').disabled=!canDaily();const userButton=$('#user-button');if(userButton)userButton.textContent=authUser?.username||'Войти';const adminLink=$('[data-admin-nav]');if(adminLink)adminLink.hidden=authUser?.role!=='admin';const soundButton=$('#sound-toggle');if(soundButton){const enabled=localStorage.getItem('ccl-sound')!=='off';soundButton.textContent=enabled?'♫':'♩';soundButton.setAttribute('aria-pressed',String(enabled));soundButton.setAttribute('aria-label',enabled?'Выключить звук':'Включить звук')}queueStateSync()}
function canDaily(){return state.dailyAt!==new Date().toLocaleDateString('en-CA')}
function toast(text,error=false){toastRoot.innerHTML=`<div class="toast ${error?'error':''}">${esc(text)}</div>`;setTimeout(()=>toastRoot.innerHTML='',2600)}
function head(kicker,title,sub='',right=''){return`<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${right}</div>`}
function caseCard(box){return`<article class="case-card"><div class="case-visual" style="--accent:${box.accent};--deep:${box.deep}"><img class="case-image" src="${box.image}" alt="Иллюстрация «${esc(box.name)}»" loading="lazy"><span class="case-image-shade"></span><span class="case-tag">${box.tag}</span></div><div class="case-info"><h3>${esc(box.name)}</h3><p>${esc(box.description)}</p><div class="case-foot"><span class="price">◈ ${fmt(box.price)}</span><div class="case-buttons"><button class="contents-btn" data-contents="${box.id}">Содержимое</button><button class="mini-btn" data-open="${box.id}">Открыть</button></div></div></div></article>`}
function itemCard(item,options={}){return`<article class="item-card" ${options.select?`data-select-item="${esc(item.uid)}"`:''}><div class="item-art" style="--rarity-color:${item.color}"><img class="item-image" src="${artFor(item)}" alt="" loading="lazy"></div><div class="item-card-body"><span class="rarity-tag" style="--rarity-color:${item.color}">${rarity(item.rarity)?.icon||'◇'} ${item.rarity}</span><h4 title="${esc(item.name)}">${esc(item.name)}</h4><span class="item-value">◈ ${fmt(item.value)}</span>${options.action?.(item)||''}</div></article>`}
function render(){route=location.hash.slice(1)||'home';document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===route));const labels={home:'ГЛАВНАЯ',cases:'КЕЙСЫ',modes:'РЕЖИМЫ',battle:'BATTLE',upgrade:'UPGRADE',contracts:'КОНТРАКТЫ',inventory:'ИНВЕНТАРЬ',collections:'КОЛЛЕКЦИИ',profile:'ПРОФИЛЬ',settings:'НАСТРОЙКИ',rules:'ПРАВИЛА',admin:'АДМИН-ПАНЕЛЬ'};$('#breadcrumb').innerHTML=`ОБЗОР <span>/</span> ${labels[route]||'ГЛАВНАЯ'}`;if(menuOpen)document.querySelector('.sidebar').style.display='flex';else document.querySelector('.sidebar').style.display='';view.innerHTML=(pages[route]||pages.home)();wire();sync();view.focus({preventScroll:true})}
function casePage(){const cards=cases.map(caseCard);return`${head('АРХИВ ЛАБОРАТОРИИ','Каталог кейсов','Выбери тему и посмотри содержимое до открытия.',`<span class="notice">${cards.length} коллекций</span>`)}<div class="case-grid">${cards.join('')}</div><p class="notice" style="margin-top:15px">Вероятности показываются до открытия. Каждый предмет — виртуальная коллекционная запись без денежной стоимости.</p>`}
function homePage(){return`<section class="hero"><div class="hero-copy"><div class="eyebrow">СЕЗОН 01 · ТИХИЙ КОСМОС</div><h1>Коллекция начинается<br>с <em>одного открытия.</em></h1><p>Открой кейс, собери собственную витрину и испытай мастерскую удачи. Здесь каждый предмет остаётся только в игре.</p><button class="btn" data-go="cases">Исследовать кейсы&nbsp; →</button></div><div class="hero-art" aria-hidden="true"><div class="hero-orb"></div><div class="hero-case"><img src="assets/cases/first-drop.webp" alt=""><span>✳</span></div></div></section><div class="stat-row"><div class="stat-card"><small>МОЙ УРОВЕНЬ</small><strong>${state.level}</strong><span>лаборант</span></div><div class="stat-card"><small>ПРЕДМЕТОВ В КОЛЛЕКЦИИ</small><strong>${state.inventory.length}</strong><span>экземпляров</span></div><div class="stat-card"><small>ОТКРЫТО КЕЙСОВ</small><strong>${state.opened}</strong><span>всего</span></div><div class="stat-card"><small>БЕСПЛАТНЫЕ ЖЕТОНЫ</small><strong>${fmt(state.balance)}</strong><span>◈</span></div></div><div class="section-head"><h2>Подобрали для тебя</h2><a class="text-link" href="#cases">Все кейсы →</a></div><div class="case-grid">${cases.slice(0,4).map(caseCard).join('')}</div><div class="section-head"><h2>В фокусе недели</h2><a class="text-link" href="#collections">Коллекции →</a></div><div class="feature-grid"><div class="feature-card"><div class="eyebrow">МЕМ НЕДЕЛИ · СМЕНЯЕМАЯ ПОДБОРКА</div><h3 style="margin-top:9px">Артефакты гаража № 7</h3><p>Пельмень-навигатор, сова на скакалке и другие неразгаданные находки. Коллекция обновляется независимо от игровых трендов.</p><button class="btn secondary small" data-go="collections">Открыть подборку</button></div><div class="feature-card"><h3>Задачи лаборатории</h3>${questsMarkup()}<a class="text-link" href="#profile">Все достижения →</a></div></div>`}
function questsMarkup(){return`<div class="quest"><span class="quest-icon">▣</span><div><strong>Загляни в коллекцию</strong><small>${Math.min(state.inventory.length,1)} / 1 предмет</small></div><b>+80 ◈</b></div><div class="quest"><span class="quest-icon">⚔</span><div><strong>Тренировочный раунд</strong><small>${state.history.some(x=>x.source==='battle')?'1 / 1':'0 / 1 раунд'}</small></div><b>+100 XP</b></div>`}
function sellAction(item){return`<button class="btn sell-stock-btn" data-sell="${esc(item.uid)}">Продать · +◈ ${fmt(Math.max(1,Math.floor(item.value*.5)))}</button>`}
function inventoryPage(){const inv=[...state.inventory];return`${head('МОЯ КОЛЛЕКЦИЯ','Склад','Предметы и их виртуальная ценность. Кнопка продажи — на каждой карточке.',`<button class="btn secondary small" data-go="cases">Найти предмет</button>`)}<div class="toolbar"><input id="inventory-search" placeholder="Найти предмет…" aria-label="Найти предмет"><select id="inventory-rarity" aria-label="Фильтр по редкости"><option value="all">Все редкости</option>${rarities.map(r=>`<option>${r.name}</option>`).join('')}</select><select id="inventory-sort" aria-label="Сортировка"><option value="new">Сначала новые</option><option value="high">Сначала ценные</option><option value="low">Сначала доступные</option><option value="rarity">По редкости</option></select><span class="result-count">${inv.length} предметов</span></div><div id="inventory-grid" class="item-grid">${inv.length?inv.map(x=>itemCard(x,{action:sellAction})).join(''):`<div class="empty-state" style="grid-column:1/-1"><span style="font-size:30px;color:var(--lime)">▤</span><strong>Коллекция пока ждёт первого предмета</strong><p>Загляни в каталог и открой бесплатный виртуальный кейс.</p><a class="btn" href="#cases">Смотреть кейсы</a></div>`}</div>`}
function battlePage(){return`${head('АРЕНА','Дружеский Battle','Симуляция с ботами. Стартовый взнос — только бесплатные игровые жетоны.') }<div class="split-layout"><div><div class="arena" id="battle-arena"><div class="arena-slot"><div class="arena-avatar">✳</div><div class="arena-name">Ты</div><div class="arena-case">▣</div><div class="arena-score" id="your-score">—</div></div><span class="versus">VS</span><div class="arena-slot"><div class="arena-avatar">◉</div><div class="arena-name">Бот · Пикс</div><div class="arena-case">▣</div><div class="arena-score" id="bot-score">—</div></div></div><div class="panel" style="margin-top:12px"><h3>Правила раунда</h3><p>Оба участника открывают выбранный кейс один раз. Побеждает сумма игровой ценности предметов. Выпавшее добавляется в обычный инвентарь только в соревновательном режиме.</p><label class="field-label" for="battle-case">Кейс для обоих игроков</label><select id="battle-case">${cases.map(c=>`<option value="${c.id}">${esc(c.name)} · ◈ ${fmt(c.price)}</option>`).join('')}</select><div style="display:flex;gap:8px;margin-top:13px;flex-wrap:wrap"><button class="btn" id="battle-start">Начать раунд</button><button class="btn secondary" id="friendly-start">Дружеский тест</button></div><p class="notice">Дружеский тест не списывает жетоны, не начисляет XP и сохраняет результат только на экране.</p></div></div><div class="panel"><h3>Последние раунды</h3>${state.history.filter(h=>h.source==='battle').slice(0,8).map(h=>`<div class="quest"><span class="quest-icon">⚔</span><div><strong>${esc(h.item.name)}</strong><small>${new Date(h.at).toLocaleDateString('ru-RU')}</small></div><b>◈ ${fmt(h.item.value)}</b></div>`).join('')||'<p>Завершённые раунды появятся здесь.</p>'}</div></div>`}
function modesPage(){return`${head('ИГРОВАЯ ПЛОЩАДКА','Режимы','Короткие раунды на бесплатных виртуальных жетонах — как в ролике.')}<div class="mode-grid"><section class="panel mode-card rocket-mode"><div class="mode-icon">🚀</div><div class="eyebrow">ЗАБЕРИ ДО ВЗРЫВА</div><h2>Ракетка</h2><p>Множитель растёт. Нажми «Забрать» раньше, чем ракета сорвётся.</p><div class="rocket-screen"><strong id="rocket-multiplier">×1.00</strong><span id="rocket-message">Готов к запуску</span></div><label class="field-label" for="mode-bet">Ставка жетонами</label><div class="mode-bet-row"><input id="mode-bet" type="number" min="10" max="1000000000000" step="10" value="200"><div class="bet-presets">${[.5,2,10,'max'].map(x=>`<button class="multiplier-btn" data-bet="${x}">${x==='max'?'MAX':`×${x}`}</button>`).join('')}</div></div><button class="btn mode-action" id="rocket-start">Запустить · ◈ 200</button><button class="btn mode-action cashout" id="rocket-cashout" hidden>Забрать</button><p class="notice">Только бесплатные жетоны внутри симулятора. Нет покупок и денежных выплат.</p></section><section class="panel mode-card ladder-mode"><div class="mode-icon">🪜</div><div class="eyebrow">ПОДНИМАЙСЯ ПО УРОВНЯМ</div><h2>Девятиэтажка</h2><p>Каждый этаж повышает множитель. Забирай выигрыш или рискуй подняться выше.</p><div class="ladder-board" id="ladder-board">${Array.from({length:9},(_,i)=>`<div data-floor="${9-i}"><span>${9-i}</span><i>×${(1.35**(9-i)).toFixed(2)}</i></div>`).join('')}</div><div class="mode-bet-row"><input id="ladder-bet" type="number" min="10" max="1000000000000" step="10" value="200" aria-label="Ставка для лестницы"><button class="btn secondary" id="ladder-start">Начать · ◈ 200</button></div><div class="mode-play-actions"><button class="btn mode-action" id="ladder-step" disabled>Подняться на этаж</button><button class="btn secondary" id="ladder-cashout" disabled>Забрать выигрыш</button></div><div id="ladder-message" class="notice">9 этажей до вершины.</div></section><section class="panel mode-card crane-mode"><div class="mode-icon">🧲</div><div class="eyebrow">НОВЫЙ РЕЖИМ · АРКАДА</div><h2>Магнитный кран</h2><p>Опусти магнит в контейнер и вытяни случайный коллекционный предмет.</p><div class="crane-stage"><div class="crane-hook">🧲</div><div class="crane-bin">▰ ▰ ▰ ▰ ▰</div></div><label class="field-label" for="crane-bet">Стоимость попытки</label><div class="mode-bet-row"><input id="crane-bet" type="number" min="10" max="1000000000000" step="10" value="500"></div><button class="btn mode-action" id="crane-play">Опустить магнит · ◈ 500</button><div id="crane-result" class="notice">Приз отправляется прямо в «Склад».</div></section><a class="panel mode-card mode-contract" href="#contracts"><div class="mode-icon">⌘</div><div class="eyebrow">ОБМЕН ПРЕДМЕТОВ</div><h2>Контракт</h2><p>Собери 5–10 находок и замени их одним случайным предметом.</p><span class="btn secondary">Открыть режим →</span></a><a class="panel mode-card mode-upgrade" href="#upgrade"><div class="mode-icon">↗</div><div class="eyebrow">МАСТЕРСКАЯ</div><h2>Апгрейд</h2><p>Испытай шанс и улучши выбранные находки.</p><span class="btn secondary">Открыть режим →</span></a></div>`}
function upgradePage(){const owned=state.inventory.filter(x=>!x.locked),targets=items.filter(x=>x.value>=100).sort((a,b)=>a.value-b.value);return`${head('МАСТЕРСКАЯ','Upgrade','Выбери ставку из предметов и цель из коллекции. Шанс и множитель показаны до запуска.') }<div class="upgrade-workspace"><section class="panel upgrade-inventory"><div class="upgrade-panel-title"><div><div class="eyebrow">ШАГ 01</div><h3>Твой предмет</h3></div><button class="btn ghost small" id="upgrade-clear">Сбросить</button></div><div id="upgrade-items" class="upgrade-owned">${owned.slice(0,24).map(x=>`<button class="pick-item upgrade-pick" data-upgrade-pick="${x.uid}" aria-pressed="false">${itemVisual(x)}<div class="item-card-body"><h4>${esc(x.name)}</h4><span class="item-value">◈ ${fmt(x.value)}</span></div></button>`).join('')||'<div class="empty-state" style="grid-column:1/-1">Инвентарь пуст.<br>Сначала открой кейс.</div>'}</div><div class="upgrade-selection-line">В ставке: <strong id="upgrade-total">0 ◈</strong></div></section><section class="upgrade-machine"><div class="upgrade-wheel-shell" id="upgrade-wheel-shell" style="--chance:0%"><div class="upgrade-wheel" id="upgrade-wheel" aria-hidden="true"></div><div class="upgrade-wheel-pointer" aria-hidden="true">▼</div><div class="upgrade-dial-inner"><span class="eyebrow">ШАНС</span><strong id="upgrade-percent">—%</strong><small id="upgrade-multiplier-label">Выбери предметы</small></div></div><div class="upgrade-modes" role="group" aria-label="Множитель цели">${[1.25,1.5,2,5,10].map(x=>`<button class="multiplier-btn ${x===upgradeMultiplier?'active':''}" data-upgrade-multiplier="${x}">×${x}</button>`).join('')}</div><p class="upgrade-outcome" id="upgrade-summary">Выбери предметы и цель, чтобы увидеть результат.</p><label style="display:flex;gap:8px;align-items:center;justify-content:center;color:#969d8e;font-size:10px;margin:8px 0"><input id="upgrade-training" type="checkbox" style="width:auto"> Тренировка без изменения коллекции</label><button class="btn upgrade-launch" id="upgrade-run" disabled>АПГРЕЙД</button><p class="notice">В основном режиме при успехе выбранные предметы заменяются целью; при неудаче они остаются.</p></section><section class="panel upgrade-target-panel"><div class="upgrade-panel-title"><div><div class="eyebrow">ШАГ 02</div><h3>Цель апгрейда</h3></div><span class="target-count">${targets.length} предметов</span></div><label class="field-label" for="upgrade-target">Предмет с нужной ценностью</label><select id="upgrade-target"><option value="">Выбрать цель…</option>${targets.map(x=>`<option value="${x.id}">${esc(x.name)} · ◈ ${fmt(x.value)} · ${x.rarity}</option>`).join('')}</select><div id="upgrade-target-preview" class="upgrade-target-preview"><div class="empty-state">Выбери цель в каталоге</div></div></section></div>`}
function contractPage(){const owned=state.inventory.filter(x=>!x.locked);return`${head('СИНТЕЗ','Контракт','Обмени 5–10 предметов на один артефакт. Диапазон и вероятности видны заранее.') }<div class="split-layout"><div class="panel"><h3>Выбери предметы</h3><p>Контракт заменит выбранные предметы одним результатом. Это действие нельзя отменить после подтверждения.</p><div class="toolbar"><span class="result-count">Выбрано: <b id="contract-count">0</b> / 10</span><button class="btn ghost small" id="contract-clear">Снять выбор</button></div><div id="contract-items" class="selected-items">${owned.map(x=>`<button class="pick-item" data-contract-pick="${x.uid}" aria-pressed="false">${itemVisual(x)}<div class="item-card-body"><h4>${esc(x.name)}</h4><span class="item-value">◈ ${fmt(x.value)}</span></div></button>`).join('')||'<p>Добавь находки из кейсов, чтобы собрать контракт.</p>'}</div></div><div class="panel"><h3>Прогноз результата</h3><div id="contract-summary" class="empty-state" style="padding:22px">Выбери от 5 до 10 предметов.</div><button class="btn" id="contract-run" disabled style="width:100%;margin-top:13px">Подтвердить контракт</button></div></div>`}
function collectionsPage(){const owned=new Set(state.inventory.map(x=>x.id));const cats=[...new Set(items.map(x=>x.category))];const all=items.length;return`${head('СЕЗОН 01 · ТИХИЙ КОСМОС','Коллекции','Собирай предметы разных тематик. Новая сезонная история хранится отдельно от трендов.') }<div class="collection-banner"><div><div class="eyebrow">МЕМ НЕДЕЛИ · ВЫМЫШЛЕННЫЙ СЛОЙ</div><h3>Гаражная фауна и другие загадки</h3><p>Оригинальная подборка без чужих изображений и аудио.</p></div><button class="btn secondary small" id="meme-switch">Сменить мемную коллекцию ↻</button></div><div class="section-head"><h2>Полки коллекции</h2><span class="notice">${owned.size} / ${all} предметов найдено</span></div><div class="stat-row">${cats.map(c=>{const coll=items.filter(x=>x.category===c),have=coll.filter(x=>owned.has(x.id)).length;return`<div class="stat-card"><small>${esc(c.toUpperCase())}</small><strong>${have} / ${coll.length}</strong><div class="progress-track" style="width:100%"><i style="width:${have/coll.length*100}%"></i></div></div>`}).join('')}</div><div class="section-head"><h2>Полный каталог предметов</h2></div><div class="item-grid">${items.slice(0,20).map(x=>itemCard(x)).join('')}</div>`}
function profilePage(){const achievements=[['✳','Первый экспонат','Добавь первый предмет в инвентарь',state.inventory.length>0],['▣','Любопытный взгляд','Открой 5 кейсов',state.opened>=5],['⚔','На арене','Заверши дружеский Battle',state.history.some(x=>x.source==='battle')],['✧','Широкий кругозор','Собери 5 разных категорий',new Set(state.inventory.map(x=>x.category)).size>=5],['◈','Исследователь','Достигни 3 уровня',state.level>=3]];return`${head('ЛИЧНОЕ ДЕЛО','Профиль',authUser?`Аккаунт ${esc(authUser.username)} · сохранение синхронизируется на сервере.`:'Прогресс хранится локально. Войди, чтобы сохранить его в аккаунте.') }<div class="stat-row"><div class="stat-card"><small>УРОВЕНЬ</small><strong>${state.level}</strong><span>лаборант</span></div><div class="stat-card"><small>ОПЫТ</small><strong>${state.xp}</strong><span>/ ${state.level*500} XP</span></div><div class="stat-card"><small>ОТКРЫТИЯ</small><strong>${state.opened}</strong><span>кейсов</span></div><div class="stat-card"><small>ЖЕТОНЫ</small><strong>${fmt(state.balance)}</strong><span>◈</span></div></div><div class="split-layout"><div class="panel"><h3>Достижения</h3>${achievements.map(a=>`<div class="achievement"><span>${a[0]}</span><div><strong>${a[1]}</strong><small>${a[2]}</small></div><i>${a[3]?'Получено':'В процессе'}</i></div>`).join('')}</div><div class="panel"><h3>Ежедневное задание</h3>${questsMarkup()}<p>Награды выдаются бесплатно за игру. Никаких таймеров давления и реальных призов.</p><h3 style="margin-top:20px">Недавние события</h3>${state.history.slice(0,5).map(h=>`<div class="quest"><span class="quest-icon">${h.source==='battle'?'⚔':'✦'}</span><div><strong>${esc(h.item.name)}</strong><small>${new Date(h.at).toLocaleString('ru-RU')}</small></div><b>◈ ${fmt(h.item.value)}</b></div>`).join('')||'<p>История появится после первого открытия.</p>'}</div></div><div class="section-head"><h2>Мои предметы</h2><a class="text-link" href="#inventory">Открыть инвентарь →</a></div><p class="notice">Продажа удаляет предмет из виртуальной коллекции и выдаёт жетоны. Денежной стоимости у предметов нет.</p><div class="item-grid">${state.inventory.slice(0,20).map(x=>itemCard(x,{action:item=>`<button class="mini-btn sell-item" data-sell="${esc(item.uid)}">Продать · +◈ ${fmt(Math.max(1,Math.floor(item.value*.5)))}</button>`})).join('')||'<div class="empty-state" style="grid-column:1/-1">Пока нечего обменивать.</div>'}</div><div class="feature-card" style="margin-top:18px"><h3>${authUser?`Вы вошли как ${esc(authUser.username)}`:'Аккаунт игрока'}</h3><p>${authUser?.role==='admin'?'Администраторская роль подтверждается сервером.':''}</p>${authUser?'<button class="btn secondary small" id="logout-button">Выйти</button>':'<button class="btn small" id="profile-login">Войти или создать аккаунт</button>'}</div>`}
function adminPage(){if(authUser?.role!=='admin')return`${head('ЗАКРЫТЫЙ РАЗДЕЛ','Админ-панель','Доступ подтверждает серверная роль администратора.') }<div class="panel" style="max-width:600px"><p>Войдите в администраторский аккаунт, чтобы открыть панель.</p><button class="btn" id="admin-login">Войти</button></div>`;return`${head('ТОЛЬКО АДМИНИСТРАТОР','Панель управления','Здесь выдаются только бесплатные игровые жетоны и виртуальные предметы.') }<div class="admin-layout"><section class="panel"><div class="eyebrow">ИГРОКИ</div><h3 style="margin-top:6px">Выбрать аккаунт</h3><input id="admin-search" placeholder="Поиск по имени игрока" aria-label="Поиск по имени игрока"><label class="field-label" for="admin-player">Аккаунт игрока</label><select id="admin-player"><option value="">Загрузка списка…</option></select><div class="admin-user-stats" id="admin-user-stats">Выбери игрока</div></section><section class="panel"><div class="eyebrow">ВИРТУАЛЬНЫЕ НАГРАДЫ</div><h3 style="margin-top:6px">Выдать жетоны или предмет</h3><label class="field-label" for="admin-tokens">Количество бесплатных жетонов</label><input id="admin-tokens" type="number" min="0" max="1000000000000000" step="1" value="0"><label class="field-label" for="admin-item">Предмет коллекции (необязательно)</label><select id="admin-item"><option value="">Без предмета</option>${items.map(x=>`<option value="${x.id}">${esc(x.name)} · ${x.rarity} · ◈ ${fmt(x.value)}</option>`).join('')}</select><button class="btn" id="admin-grant" style="margin-top:15px;width:100%">Выдать выбранную награду</button><p class="notice">Операция сохраняется сервером в аккаунте выбранного игрока. Реальных денег, вывода и денежных предметов нет.</p></section></div><section class="panel" style="margin-top:14px"><h3>Последние выдачи</h3><p>Изменения баланса и предметов в аккаунтах проходят через защищённый серверный endpoint.</p></section>`}
function settingsPage(){return`${head('ЛОКАЛЬНО И В АККАУНТЕ','Настройки','Прогресс гостя хранится в браузере; аккаунты сохраняются сервером.') }<div class="panel" style="max-width:580px"><h3>Приватность и данные</h3><p>${authUser?'Игровой прогресс аккаунта хранится в локальной базе сервера. Пароли хранятся в виде стойких хешей.':'Гостевой баланс и предметы остаются в localStorage браузера.'}</p><button class="btn danger" id="reset-progress">Сбросить локальный прогресс</button><p class="notice">Сброс удалит баланс, уровень, коллекцию и историю текущего аккаунта в этом браузере.</p><button class="btn secondary small" data-go="rules">Правила и ограничения</button></div>`}
function rulesPage(){return`${head('ПРОЗРАЧНО И БЕЗОПАСНО','Правила и ограничения','Коротко о том, как устроена лаборатория.') }<article class="panel rules"><h2>Виртуальная игра</h2><p>Case Clash Lab — учебный и развлекательный симулятор. Жетоны, предметы и результаты существуют только внутри сайта, не имеют денежной стоимости, не продаются и не обмениваются на товары или услуги.</p><h2>Без платежей и внешних аккаунтов</h2><p>Нет ставок, пополнений, вывода, криптовалюты, денежных призов, интеграции с игровыми площадками или внешнего инвентаря. Не вводите банковские данные, пароли или токены.</p><h2>Шансы и честный результат</h2><p>Шансы редкости отображаются до открытия. Результат выбирается единожды перед анимацией; лента показывает его и не переигрывает выпадение. Внешний вид ленты не влияет на шанс.</p><h2>Возраст и контент</h2><p>Рекомендуемый возраст: 12+. Здесь есть игровые случайные открытия и шуточные предметы. Если вы несовершеннолетний, соблюдайте правила семьи и делайте перерывы.</p><h2>Хранение</h2><p>Прогресс локальный и остаётся в браузере устройства. Очистка данных сайта или кнопка сброса удалит его.</p><a class="text-link" href="#home">← Вернуться на главную</a></article>`}
const pages={home:homePage,cases:casePage,modes:modesPage,battle:battlePage,upgrade:upgradePage,contracts:contractPage,inventory:inventoryPage,collections:collectionsPage,profile:profilePage,settings:settingsPage,rules:rulesPage,admin:adminPage};
function showModal(title,content){modalRoot.innerHTML=`<div class="modal-backdrop" role="presentation"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="modal-close" aria-label="Закрыть">×</button></div><div class="modal-content">${content}</div></section></div>`;modalRoot.querySelector('.modal-close').focus();modalRoot.querySelector('.modal-close').onclick=closeModal;modalRoot.querySelector('.modal-backdrop').onclick=e=>{if(e.target===e.currentTarget)closeModal()};document.addEventListener('keydown',escapeModal,{once:true})}
function escapeModal(e){if(e.key==='Escape')closeModal()}
function closeModal(){modalRoot.innerHTML='';}
function accountModal(mode='login'){const isRegister=mode==='register';showModal(isRegister?'Создать аккаунт игрока':'Вход в Case Clash Lab',`<form id="account-form"><label class="field-label" for="account-name">Имя аккаунта</label><input id="account-name" name="username" autocomplete="username" minlength="3" maxlength="24" required><label class="field-label" for="account-password">Пароль</label><input id="account-password" name="password" type="password" autocomplete="${isRegister?'new-password':'current-password'}" minlength="${isRegister?'10':'1'}" maxlength="128" required><p class="notice">${isRegister?'Создаётся обычный аккаунт игрока; регистрация не выдаёт права администратора. Пароль от 10 символов.':'Администраторская роль назначается только на сервере.'}</p><div id="account-error" class="notice" role="status"></div><div class="modal-actions"><button class="btn secondary" type="button" data-modal-close>Отмена</button><button class="btn" type="submit">${isRegister?'Создать аккаунт':'Войти'}</button></div></form><p class="notice">${isRegister?'Уже есть аккаунт?':'Нет аккаунта?'} <button class="text-link" type="button" id="account-switch">${isRegister?'Войти':'Создать аккаунт'}</button></p>`);modalRoot.querySelector('[data-modal-close]').onclick=closeModal;modalRoot.querySelector('#account-switch').onclick=()=>accountModal(isRegister?'login':'register');modalRoot.querySelector('#account-form').onsubmit=async e=>{e.preventDefault();const username=$('#account-name').value.trim(),password=$('#account-password').value;try{const user=await api(isRegister?'/api/auth/register':'/api/auth/login',{method:'POST',body:JSON.stringify({username,password})});closeModal();applyAccount(user);toast(isRegister?'Аккаунт создан':'Вход выполнен')}catch(err){$('#account-error').textContent=err.message}}}
async function loadAdminUsers(query=''){const select=$('#admin-player');if(!select)return;try{const result=await api(`/api/admin/users?q=${encodeURIComponent(query)}`);select.innerHTML=result.users.map(u=>`<option value="${u.id}">${esc(u.username)} · ◈ ${fmt(u.balance)} · ${u.items} предм.</option>`).join('')||'<option value="">Игроки не найдены</option>';updateAdminPlayer()}catch(e){select.innerHTML='<option value="">Не удалось загрузить список</option>';toast(e.message,true)}}
async function updateAdminPlayer(){const id=$('#admin-player')?.value;if(!id)return;try{const result=await api(`/api/admin/users`);const u=result.users.find(x=>x.id===id);$('#admin-user-stats').textContent=u?`${u.username} · ◈ ${fmt(u.balance)} жетонов · ${u.items} предметов`:''}catch{}}
async function grantAdminReward(){const userId=$('#admin-player')?.value,tokens=Number($('#admin-tokens')?.value||0),itemId=$('#admin-item')?.value||'';if(!userId)return toast('Сначала выбери игрока',true);try{const result=await api('/api/admin/grant',{method:'POST',body:JSON.stringify({userId,tokens,itemId:itemId||null})});toast(`Выдано аккаунту ${result.user.username}: +◈ ${fmt(tokens)}${result.item?` и ${result.item.name}`:''}`);await loadAdminUsers($('#admin-search')?.value||'')}catch(e){toast(e.message,true)}}
function oddsMarkup(box){return box.tiers.map((p,i)=>p>0?`<div class="odds-row"><span style="--rarity-color:${rarities[i].color}">${rarities[i].icon} ${rarities[i].name}</span><b>${(p*100).toFixed(p*100%1?1:0)}%</b></div>`:'').join('')}
function showContents(box){const inside=box.items.map(x=>`<div class="small-item" style="--rarity-color:${x.color}">${itemVisual(x)}<strong>${esc(x.name)}</strong><span class="rarity-tag" style="--rarity-color:${x.color}">${x.rarity} · ◈ ${fmt(x.value)}</span></div>`).join('');showModal(esc(box.name),`<p class="notice">${esc(box.description)} Стоимость: ◈ ${fmt(box.price)} · Возможная ценность: ◈ ${fmt(Math.min(...box.items.map(x=>x.value)))}—${fmt(Math.max(...box.items.map(x=>x.value)))}.</p><h3 style="font-size:12px;margin:16px 0 8px">Шанс по редкости</h3><div class="odds-list">${oddsMarkup(box)}</div><h3 style="font-size:12px;margin:18px 0 8px">Содержимое (${box.items.length})</h3><div class="modal-item-grid">${inside}</div><p class="notice" style="margin-top:12px">Предметы виртуальные и не имеют денежной стоимости.</p><div class="modal-actions"><button class="btn secondary" data-modal-close>Закрыть</button><button class="btn" data-modal-open="${box.id}">Открыть за ◈ ${fmt(box.price)}</button></div>`);modalRoot.querySelector('[data-modal-close]').onclick=closeModal;modalRoot.querySelector('[data-modal-open]').onclick=()=>openCase(box.id)}
function openCase(id){const box=cases.find(x=>x.id===id);if(!box)return;if(state.balance<box.price){playSound('fail');toast('Недостаточно жетонов. Забери ежедневную награду.',true);return}openedCaseId=id;playSound('spin');const outcome=pickCaseItem(box);state.balance-=box.price;sync();const pool=box.items,tiles=Array.from({length:31},()=>pool[Math.floor(Math.random()*pool.length)]);tiles[25]=outcome;const seq=tiles.map(it=>`<div class="roulette-tile" style="--rarity-color:${it.color}">${itemVisual(it)}<small>${esc(it.name)}</small></div>`).join('');showModal(`Открываем · ${esc(box.name)}`,`<p class="notice">Результат определён до начала анимации. Лента не влияет на шанс выпадения.</p><div class="roulette-window"><div class="roulette-track">${seq}</div></div><div class="modal-actions"><button class="btn ghost small" id="skip-spin">Пропустить анимацию</button></div><div id="spin-result" hidden></div>`);let done=false;const finish=()=>{if(done)return;done=true;const owned=addItem(state,outcome,`Кейс: ${box.name}`);sync();playSound(['Обычный','Необычный'].includes(outcome.rarity)?'reveal':'win');const result=$('#spin-result');result.hidden=false;result.innerHTML=`<div class="result-card" style="--rarity-color:${outcome.color}">${itemVisual(outcome)}<span class="rarity-tag" style="--rarity-color:${outcome.color}">${rarity(outcome.rarity).icon} ${outcome.rarity}</span><h3>${esc(outcome.name)}</h3><p>Виртуальная ценность: ◈ ${fmt(outcome.value)} · Предмет добавлен в инвентарь</p></div><div class="modal-actions"><button class="btn secondary" id="result-close">Готово</button><button class="btn" id="open-again">Ещё раз · ◈ ${fmt(box.price)}</button></div>`;$('#result-close').onclick=()=>{closeModal();render()};$('#open-again').onclick=()=>{closeModal();openCase(box.id)}};const track=modalRoot.querySelector('.roulette-track');const rouletteWindow=modalRoot.querySelector(".roulette-window"),winnerTile=track.children[25],tileRect=winnerTile.getBoundingClientRect(),windowRect=rouletteWindow.getBoundingClientRect();const targetX=rouletteWindow.clientWidth/2-((tileRect.left-windowRect.left)+tileRect.width/2);track.style.setProperty('--stop',`${targetX}px`);track.style.animation='spin-down 3.6s cubic-bezier(.07,.78,.05,1) forwards';const timer=setTimeout(finish,3650);$('#skip-spin').onclick=()=>{clearTimeout(timer);track.style.animation='none';track.style.transform=`translateX(${targetX}px)`;finish()}}
function doDaily(){if(!canDaily())return;state.dailyAt=new Date().toLocaleDateString('en-CA');state.balance+=500;addXp(state,50);sync();playSound('win');toast('Ежедневная награда: +500 ◈ и +50 XP');render()}
function wire(){document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>location.hash=x.dataset.go);document.querySelectorAll('[data-contents]').forEach(x=>x.onclick=()=>showContents(cases.find(c=>c.id===x.dataset.contents)));document.querySelectorAll('[data-open]').forEach(x=>x.onclick=()=>openCase(x.dataset.open));$('#daily-button').onclick=doDaily;$('#sound-toggle')?.addEventListener('click',()=>{const next=localStorage.getItem('ccl-sound')==='off'?'on':'off';localStorage.setItem('ccl-sound',next);sync();if(next==='on')playSound('reveal')});$('#mobile-menu').onclick=()=>{menuOpen=!menuOpen;render()};$('#user-button').onclick=()=>authUser?location.hash='profile':accountModal();$('#profile-login')?.addEventListener('click',()=>accountModal());$('#admin-login')?.addEventListener('click',()=>accountModal());$('#logout-button')?.addEventListener('click',logout);
  document.querySelectorAll('[data-upgrade-pick]').forEach(b=>b.onclick=()=>{const id=b.dataset.upgradePick;selectedUpgrade=selectedUpgrade.includes(id)?selectedUpgrade.filter(x=>x!==id):[...selectedUpgrade,id];b.classList.toggle('selected',selectedUpgrade.includes(id));b.setAttribute('aria-pressed',String(selectedUpgrade.includes(id)));updateUpgrade()});
  document.querySelectorAll('[data-upgrade-multiplier]').forEach(b=>b.onclick=()=>{upgradeMultiplier=Number(b.dataset.upgradeMultiplier);document.querySelectorAll('[data-upgrade-multiplier]').forEach(x=>x.classList.toggle('active',x===b));const value=selectedUpgradeItems().reduce((a,x)=>a+x.value,0);if(value){const target=items.filter(x=>x.value>=value*upgradeMultiplier).sort((a,b)=>a.value-b.value)[0];if(target)$('#upgrade-target').value=target.id}updateUpgrade()});
  $('#upgrade-clear')?.addEventListener('click',()=>{selectedUpgrade=[];updateUpgrade();render()});$('#upgrade-target')?.addEventListener('change',updateUpgrade);$('#upgrade-training')?.addEventListener('change',updateUpgrade);$('#upgrade-run')?.addEventListener('click',runUpgrade);
  document.querySelectorAll('[data-contract-pick]').forEach(b=>b.onclick=()=>{const id=b.dataset.contractPick;if(selectedBattle.includes(id))selectedBattle=selectedBattle.filter(x=>x!==id);else if(selectedBattle.length<10)selectedBattle.push(id);else toast('В контракте может быть до 10 предметов',true);b.classList.toggle('selected',selectedBattle.includes(id));b.setAttribute('aria-pressed',String(selectedBattle.includes(id)));updateContract()});$('#contract-clear')?.addEventListener('click',()=>{selectedBattle=[];render()});$('#contract-run')?.addEventListener('click',runContract);
  wireSellButtons();$('#admin-search')?.addEventListener('input',()=>{clearTimeout(window.adminSearchTimer);window.adminSearchTimer=setTimeout(()=>loadAdminUsers($('#admin-search').value),200)});$('#admin-player')?.addEventListener('change',updateAdminPlayer);$('#admin-grant')?.addEventListener('click',grantAdminReward);if(route==='admin'&&authUser?.role==='admin')loadAdminUsers();
  $('#inventory-search')?.addEventListener('input',filterInventory);$('#inventory-rarity')?.addEventListener('change',filterInventory);$('#inventory-sort')?.addEventListener('change',filterInventory);$('#battle-start')?.addEventListener('click',()=>runBattle(false));$('#friendly-start')?.addEventListener('click',()=>runBattle(true));document.querySelectorAll('[data-bet]').forEach(b=>b.addEventListener('click',()=>{const input=$('#mode-bet'),factor=b.dataset.bet;input.value=factor==='max'?state.balance:Math.max(10,Math.floor((Number(input.value)||200)*Number(factor)));updateModeBet('mode-bet','rocket-start','Запустить')}));$('#mode-bet')?.addEventListener('input',()=>updateModeBet('mode-bet','rocket-start','Запустить'));$('#rocket-start')?.addEventListener('click',startRocket);$('#rocket-cashout')?.addEventListener('click',cashoutRocket);$('#ladder-start')?.addEventListener('click',startLadder);$('#ladder-step')?.addEventListener('click',climbLadder);$('#ladder-cashout')?.addEventListener('click',cashoutLadder);$('#ladder-bet')?.addEventListener('input',()=>updateModeBet('ladder-bet','ladder-start','Начать'));$('#crane-bet')?.addEventListener('input',()=>updateModeBet('crane-bet','crane-play','Опустить магнит'));$('#crane-play')?.addEventListener('click',playCrane);$('#reset-progress')?.addEventListener('click',()=>showModal('Сбросить локальный прогресс?',`<p>Будут удалены жетоны, уровень, предметы и история. Это действие нельзя отменить.</p><div class="modal-actions"><button class="btn secondary" data-modal-close>Отмена</button><button class="btn danger" id="confirm-reset">Сбросить</button></div>`));$('#confirm-reset')?.addEventListener('click',()=>{state={...loadState(authUser?.id||'guest'),balance:1200,xp:0,level:1,inventory:[],history:[],dailyAt:'',opened:0};saveState(state,authUser?.id||'guest');selectedBattle=[];selectedUpgrade=[];closeModal();location.hash='home';render();toast('Локальный прогресс сброшен')});$('#meme-switch')?.addEventListener('click',()=>{state.season=(state.season+1)%3;sync();const labels=['Гаражная фауна и другие загадки','Космическая мастерская: странные смены','Пыльный архив: предметы вне каталога'];const h=document.querySelector('.collection-banner h3');if(h)h.textContent=labels[state.season];toast('Подборка мемов обновлена')});}
async function logout(){try{await api('/api/auth/logout',{method:'POST'})}catch{}authUser=null;state=loadState('guest');selectedUpgrade=[];location.hash='home';render();toast('Вы вышли из аккаунта')}
async function sellProfileItem(uid){const index=state.inventory.findIndex(x=>x.uid===uid);if(index<0)return;const item=state.inventory[index],tokens=Math.max(1,Math.floor(item.value*.5)),before=Number(state.balance)||0;state.inventory.splice(index,1);state.balance=before+tokens;state.history.unshift({item,source:`Продажа со склада · +◈ ${tokens}`,at:new Date().toISOString()});const accountId=authUser?.id||'guest';saveState(state,accountId);sync();render();playSound('win');toast(`+◈ ${fmt(tokens)} · баланс ${fmt(before)} → ${fmt(state.balance)}`);if(authUser)try{await api('/api/state',{method:'POST',body:JSON.stringify(state)})}catch{toast('Жетоны добавлены. Серверное сохранение не удалось — проверь соединение.',true)}}
function wireSellButtons(){document.querySelectorAll('[data-sell]').forEach(b=>b.onclick=()=>sellProfileItem(b.dataset.sell))}
function filterInventory(){const q=$('#inventory-search').value.toLocaleLowerCase('ru'),r=$('#inventory-rarity').value,sort=$('#inventory-sort').value;let arr=state.inventory.filter(x=>x.name.toLocaleLowerCase('ru').includes(q)&&(r==='all'||x.rarity===r));if(sort==='high')arr.sort((a,b)=>b.value-a.value);if(sort==='low')arr.sort((a,b)=>a.value-b.value);if(sort==='rarity')arr.sort((a,b)=>gradeIndex(b.rarity)-gradeIndex(a.rarity));const grid=$('#inventory-grid');grid.innerHTML=arr.map(x=>itemCard(x,{action:sellAction})).join('')||'<div class="empty-state" style="grid-column:1/-1">По этому фильтру предметов нет.</div>';document.querySelector('.result-count').textContent=`${arr.length} предметов`;wireSellButtons()}
function selectedUpgradeItems(){return state.inventory.filter(x=>selectedUpgrade.includes(x.uid))}
function updateUpgrade(){const picks=selectedUpgradeItems(),value=picks.reduce((a,x)=>a+x.value,0),target=items.find(x=>x.id===$('#upgrade-target')?.value),training=$('#upgrade-training')?.checked,sum=$('#upgrade-summary'),run=$('#upgrade-run');if(!sum)return;$('#upgrade-total').textContent=`${fmt(value)} ◈`;const dial=$('#upgrade-wheel-shell'),percent=$('#upgrade-percent'),label=$('#upgrade-multiplier-label'),preview=$('#upgrade-target-preview');if(preview)preview.innerHTML=target?`${itemVisual(target)}<span class="rarity-tag" style="--rarity-color:${target.color}">${rarity(target.rarity)?.icon||'◇'} ${target.rarity}</span><strong>${esc(target.name)}</strong><b>◈ ${fmt(target.value)}</b>`:'<div class="empty-state">Выбери цель в каталоге</div>';if(!picks.length||!target){sum.textContent='Выбери предметы и цель, чтобы увидеть результат.';percent.textContent='—%';label.textContent=picks.length?'Выбери цель':'Выбери предметы';dial?.style.setProperty('--chance','0%');run.disabled=true;return}const chance=Math.min(.98,value/target.value),actualMultiplier=target.value/value;dial.style.setProperty('--chance',`${chance*100}%`);percent.textContent=`${(chance*100).toFixed(2)}%`;label.textContent=`×${actualMultiplier.toFixed(2)} · ◈ ${fmt(target.value)}`;sum.innerHTML=`<span>Ставка <b>◈ ${fmt(value)}</b></span><span>Цель <b>◈ ${fmt(target.value)}</b></span><span>${training?'В тренировке предметы сохраняются':'При успехе цель заменит выбранные предметы'}</span><span>При неудаче выбранные предметы остаются.</span>`;run.disabled=false;run.textContent=`АПГРЕЙД · ${(chance*100).toFixed(2)}%`}
function runUpgrade(){const picks=selectedUpgradeItems(),target=items.find(x=>x.id===$('#upgrade-target')?.value),training=$('#upgrade-training')?.checked;if(!picks.length||!target||upgradeBusy)return;const value=picks.reduce((a,x)=>a+x.value,0),chance=Math.min(.98,value/target.value),roll=Math.random(),success=roll<chance,wheel=$('#upgrade-wheel'),shell=$('#upgrade-wheel-shell'),run=$('#upgrade-run');upgradeBusy=true;if(shell){shell.classList.remove('upgrade-win','upgrade-loss');shell.style.setProperty('--chance',`${chance*100}%`)}if(wheel){wheel.style.transition='none';wheel.style.transform='rotate(0deg)';void wheel.offsetWidth;wheel.style.transition='transform 4s cubic-bezier(.11,.72,.06,1)';wheel.style.transform=`rotate(${5*360+(360-roll*360)}deg)`}if(run){run.disabled=true;run.textContent='КОЛЕСО КРУТИТСЯ…'}playSound('spin');setTimeout(()=>{upgradeBusy=false;shell?.classList.add(success?'upgrade-win':'upgrade-loss');if(success&&!training){const ids=new Set(picks.map(x=>x.uid));state.inventory=state.inventory.filter(x=>!ids.has(x.uid));addItem(state,target,'Upgrade');playSound('win')}else playSound(success?'win':'fail');selectedUpgrade=[];document.querySelectorAll('[data-upgrade-pick].selected').forEach(button=>{button.classList.remove('selected');button.setAttribute('aria-pressed','false')});sync();const title=success?'Успешный апгрейд!':'Неудача';const detail=success?training?'Тренировочный успех — коллекция не изменилась.':`Ты получил предмет «${esc(target.name)}».`:'Предметы ставки сохранены.';const reward=success&&!training?`<div class="result-card upgrade-result-item" style="--rarity-color:${target.color}">${itemVisual(target)}<span class="rarity-tag" style="--rarity-color:${target.color}">${rarity(target.rarity)?.icon||'◇'} ${target.rarity}</span><h3>${esc(target.name)}</h3><b>◈ ${fmt(target.value)}</b></div>`:'';showModal(`Upgrade · ${title}`,`<div class="upgrade-result ${success?'success':'failure'}"><span class="eyebrow">ШАНС БЫЛ ${(chance*100).toFixed(2)}%</span><h2>${title}</h2><p>${detail}</p>${reward}<p class="notice">${training?'Тренировочный режим не меняет инвентарь.':'Вероятность определяет результат; колесо только показывает этот бросок.'}</p><button class="btn" id="upgrade-result-close">Продолжить</button></div>`);const finish=()=>{if(upgradeBusy)return;closeModal();render()};$('#upgrade-result-close').onclick=finish;modalRoot.querySelector('.modal-close').onclick=finish;modalRoot.querySelector('.modal-backdrop').onclick=event=>{if(event.target===event.currentTarget)finish()}},4100)}
function modeStake(id){const input=$(`#${id}`);return Math.max(0,Math.floor(Number(input?.value)||0))}
function updateModeBet(id,buttonId,label){const input=$(`#${id}`),button=$(`#${buttonId}`);if(input&&button)button.textContent=`${label} · ◈ ${fmt(Number(input.value)||0)}`}
function startRocket(){if(rocketRun)return;const stake=modeStake('mode-bet');if(stake<10||state.balance<stake)return toast('Нужна ставка от 10 жетонов и достаточный баланс',true);state.balance-=stake;rocketRun={stake,multiplier:1,crashAt:1.15+Math.random()*5.85,started:performance.now()};$('#rocket-multiplier').classList.remove('crashed');$('#rocket-message').textContent='Ракета в полёте';$('#rocket-start').hidden=true;$('#rocket-cashout').hidden=false;sync();playSound('rocket');rocketTimer=setInterval(()=>{if(!rocketRun)return;const elapsed=(performance.now()-rocketRun.started)/1000;rocketRun.multiplier=1+elapsed*elapsed*.42+elapsed*.35;$('#rocket-multiplier').textContent=`×${rocketRun.multiplier.toFixed(2)}`;if(rocketRun.multiplier>=rocketRun.crashAt){clearInterval(rocketTimer);rocketTimer=null;rocketRun=null;$('#rocket-multiplier').classList.add('crashed');$('#rocket-message').textContent='Взрыв! Ставка сгорела';$('#rocket-start').hidden=false;$('#rocket-cashout').hidden=true;playSound('crash');toast('Ракета взорвалась — ставка потеряна',true)}},45)}
function cashoutRocket(){if(!rocketRun)return;clearInterval(rocketTimer);rocketTimer=null;const {stake,multiplier}=rocketRun;rocketRun=null;const payout=Math.floor(stake*multiplier);state.balance+=payout;$('#rocket-multiplier').classList.remove('crashed');$('#rocket-message').textContent=`Забрал ×${multiplier.toFixed(2)} · +◈ ${fmt(payout)}`;$('#rocket-start').hidden=false;$('#rocket-cashout').hidden=true;sync();playSound('win');toast(`Вывод до взрыва: +◈ ${fmt(payout)}`)}
function startLadder(){if(ladderRun)return;const stake=modeStake('ladder-bet');if(stake<10||state.balance<stake)return toast('Нужна ставка от 10 жетонов и достаточный баланс',true);state.balance-=stake;ladderRun={stake,floor:0,multiplier:1};document.querySelectorAll('[data-floor]').forEach(x=>x.classList.remove('cleared','failed'));$('#ladder-message').textContent='Ставка принята. Поднимайся или забирай.';$('#ladder-step').disabled=false;$('#ladder-cashout').disabled=false;$('#ladder-start').disabled=true;sync();playSound('step')}
function climbLadder(){if(!ladderRun)return;const success=Math.random()<.72;const next=ladderRun.floor+1;const tile=$(`[data-floor="${10-next}"]`);if(!success){tile?.classList.add('failed');$('#ladder-message').textContent='Неудачный шаг — ставка потеряна';ladderRun=null;$('#ladder-step').disabled=true;$('#ladder-cashout').disabled=true;$('#ladder-start').disabled=false;playSound('fail');return}ladderRun.floor=next;ladderRun.multiplier=1.38**next;tile?.classList.add('cleared');$('#ladder-message').textContent=`Этаж ${next}/9 · можно забрать ◈ ${fmt(ladderRun.stake*ladderRun.multiplier)}`;playSound('step');if(next===9)cashoutLadder()}
function cashoutLadder(){if(!ladderRun||ladderRun.floor===0)return toast('Сначала поднимись хотя бы на один этаж',true);const payout=Math.floor(ladderRun.stake*ladderRun.multiplier);state.balance+=payout;ladderRun=null;$('#ladder-message').textContent=`Выигрыш забран: +◈ ${fmt(payout)}`;$('#ladder-step').disabled=true;$('#ladder-cashout').disabled=true;$('#ladder-start').disabled=false;sync();playSound('win')}
function playCrane(){const stake=modeStake('crane-bet');if(stake<10||state.balance<stake)return toast('Нужна ставка от 10 жетонов и достаточный баланс',true);state.balance-=stake;playSound('crane');const pool=items.filter(x=>x.value<=Math.max(stake*8,items[0].value));const prize=weightedPick(pool.map(x=>({item:x,weight:1/Math.sqrt(Math.max(1,x.value))})));addItem(state,prize,'Магнитный кран');$('#crane-result').innerHTML=`Кран вытащил <b>${esc(prize.name)}</b> · ◈ ${fmt(prize.value)} — уже в складе`;sync();playSound(prize.rarity==='Обычный'?'reveal':'win')}
function selectedContractItems(){return state.inventory.filter(x=>selectedBattle.includes(x.uid))}
function updateContract(){const chosen=selectedContractItems(),count=$('#contract-count'),summary=$('#contract-summary'),run=$('#contract-run');if(!count||!summary)return;count.textContent=chosen.length;const valid=chosen.length>=5&&chosen.length<=10;run.disabled=!valid;if(!valid){summary.className='empty-state';summary.textContent=`Нужно выбрать от 5 до 10 предметов. Сейчас выбрано: ${chosen.length}.`;return}const avg=chosen.reduce((a,x)=>a+x.value,0)/chosen.length;const eligible=items.filter(x=>x.value<=avg*3+20),probs=eligible.map(x=>({item:x,weight:Math.max(.05,1-Math.abs(x.value-avg*1.5)/(avg*3+20))}));const all=probs.reduce((a,x)=>a+x.weight,0),byRarity=rarities.map(r=>({r,p:probs.filter(x=>x.item.rarity===r.name).reduce((a,x)=>a+x.weight,0)/all})).filter(x=>x.p>0);summary.className='panel';summary.innerHTML=`<p>Средняя ценность обмена: <b>◈ ${fmt(avg)}</b></p><p>Диапазон результата: <b>◈ ${fmt(Math.min(...eligible.map(x=>x.value)))}–${fmt(Math.max(...eligible.map(x=>x.value)))}</b></p><p>Вероятность редкости:</p>${byRarity.map(x=>`<div class="odds-row"><span style="--rarity-color:${x.r.color}">${x.r.icon} ${x.r.name}</span><b>${(x.p*100).toFixed(1)}%</b></div>`).join('')}<p>Старые предметы будут заменены одним новым.</p>`}
function runContract(){const chosen=selectedContractItems();if(chosen.length<5||chosen.length>10)return;const avg=chosen.reduce((a,x)=>a+x.value,0)/chosen.length,eligible=items.filter(x=>x.value<=avg*3+20),entries=eligible.map(x=>({item:x,weight:Math.max(.05,1-Math.abs(x.value-avg*1.5)/(avg*3+20))})),result=weightedPick(entries);showModal('Подтвердить контракт',`<p>Выбранные ${chosen.length} предметов будут заменены одним предметом. Это действие нельзя отменить.</p><div class="result-card" style="--rarity-color:${result.color}">${itemVisual(result)}<h3>Возможный пример: ${esc(result.name)}</h3><p>Диапазон ценности предметов результата: ◈ ${fmt(Math.min(...eligible.map(x=>x.value)))}–${fmt(Math.max(...eligible.map(x=>x.value)))}</p></div><div class="modal-actions"><button class="btn secondary" data-modal-close>Отмена</button><button class="btn" id="confirm-contract">Подтвердить синтез</button></div>`);$('#confirm-contract').onclick=()=>{const ids=new Set(chosen.map(x=>x.uid));state.inventory=state.inventory.filter(x=>!ids.has(x.uid));addItem(state,result,'Контракт');selectedBattle=[];sync();closeModal();render();toast(`Контракт завершён: ${result.name}`)}}
function runBattle(friendly){const box=cases.find(x=>x.id===$('#battle-case')?.value)||cases[0];if(!friendly&&state.balance<box.price){toast('Недостаточно жетонов для раунда',true);return}if(!friendly)state.balance-=box.price;const mine=pickCaseItem(box),bot=pickCaseItem(box);if(!friendly)addItem(state,mine,'battle');sync();$('#your-score').textContent=`◈ ${fmt(mine.value)}`;$('#bot-score').textContent=`◈ ${fmt(bot.value)}`;const banner=document.querySelector('.arena');banner?.insertAdjacentHTML('beforeend',`<div class="result-card" style="--rarity-color:${mine.color};position:absolute;z-index:2;max-width:280px"><span style="font-size:27px;color:${mine.color}">${mine.icon}</span><h3>${esc(mine.name)}</h3><p>Бот нашёл «${esc(bot.name)}» · ◈ ${fmt(bot.value)}</p><strong style="color:var(--lime)">${mine.value>bot.value?'Ты выиграл раунд':mine.value<bot.value?'Бот выиграл раунд':'Ничья'}</strong><br><button class="btn secondary small" style="margin-top:10px" id="dismiss-battle">Продолжить</button></div>`);banner.style.position='relative';$('#dismiss-battle').onclick=()=>{const card=banner.querySelector('.result-card');card?.remove()};if(mine.value>bot.value){playSound('win');toast(friendly?'Тестовая победа!':'Победа в раунде!')}else{playSound('reveal');toast('Раунд завершён')}}
document.addEventListener('pointerdown',event=>{if(event.target.closest('button'))playSound('click')},{capture:true});window.addEventListener('hashchange',()=>{selectedBattle=[];selectedUpgrade=[];menuOpen=false;render()});render();bootstrapAuth();
